import { http } from '@/shared/api/httpClient';
import type { TitleDetail } from '@/shared/api/types';

export function fetchTitle(id: number): Promise<TitleDetail> {
  return http.get<TitleDetail>(`/titles/${id}`);
}

export function rateTitle(
  id: number,
  score: number,
): Promise<{ ratingAvg: number; ratingCount: number; myRating: number }> {
  return http.put(`/titles/${id}/rating`, { score });
}

export function unrateTitle(id: number): Promise<void> {
  return http.del(`/titles/${id}/rating`);
}
